-- ============================================================================
-- XTROVERT — production integration (CURRENT LIVE STATE, regenerated by
-- reading the actual database directly — every table, policy, grant, and
-- function below was verified against production, not reconstructed from
-- memory). Safe to re-run: every statement is idempotent.
--
-- Run supabase/schema.sql FIRST (ranks + profiles), then this file.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) DAILY QUOTES — server-curated only. RLS is enabled with ZERO policies,
--    meaning no role (not even authenticated) can query this table directly
--    at all. The ONLY way to read a quote is get_daily_quote() below, which
--    is SECURITY DEFINER and bypasses RLS deliberately, on purpose, as the
--    single controlled door in. Nobody can INSERT/UPDATE/DELETE a quote from
--    the client under any circumstances.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.daily_quotes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  quote_text  text NOT NULL CHECK (length(btrim(quote_text)) > 0),
  author      text NOT NULL DEFAULT 'Field Doctrine',
  is_active   boolean NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.daily_quotes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.daily_quotes FROM anon, authenticated;
-- Intentionally NO policies of any kind on this table.

-- ----------------------------------------------------------------------------
-- 2) CHALLENGES — read-only for logged-in users, writable only by you
--    (service_role / SQL editor).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.challenges (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title          text NOT NULL,
  description    text NOT NULL,
  difficulty     text NOT NULL DEFAULT 'Medium',
  xp_reward      integer NOT NULL DEFAULT 50,
  required_rank  text NOT NULL DEFAULT 'Starter',
  is_active      boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.challenges ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.challenges FROM anon, authenticated;
GRANT SELECT ON public.challenges TO authenticated;

DROP POLICY IF EXISTS "Active challenges are viewable by authenticated users" ON public.challenges;
CREATE POLICY "Active challenges are viewable by authenticated users"
  ON public.challenges
  FOR SELECT
  TO authenticated
  USING (is_active = true);
-- No INSERT/UPDATE/DELETE policy or grant -> clients cannot add/edit challenges.

-- ----------------------------------------------------------------------------
-- 3) USER_COMPLETED_CHALLENGES — history of completions. Read-only for the
--    client; the only path that ever writes a row is complete_challenge().
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_completed_challenges (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  challenge_id  uuid NOT NULL REFERENCES public.challenges (id) ON DELETE CASCADE,
  xp_awarded    integer NOT NULL,
  completed_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, challenge_id)
);

ALTER TABLE public.user_completed_challenges ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_completed_challenges FROM anon, authenticated;
GRANT SELECT ON public.user_completed_challenges TO authenticated;
-- Deliberately NO insert grant — even though a defensive RLS policy exists
-- below in case grants are ever loosened by mistake, the current live grant
-- set already makes direct inserts impossible. complete_challenge() is the
-- only writer (it runs as the function owner, not as your role).

DROP POLICY IF EXISTS "Users can view own completions" ON public.user_completed_challenges;
CREATE POLICY "Users can view own completions"
  ON public.user_completed_challenges
  FOR SELECT
  TO authenticated
  USING (auth.uid() = user_id);

-- ----------------------------------------------------------------------------
-- 4) JOURNAL_ENTRIES — strictly private. Read-only for the client; the only
--    writers are add_journal_entry() (free-form) and complete_challenge()
--    (challenge-linked). No direct INSERT grant exists.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.journal_entries (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  challenge_id    uuid REFERENCES public.challenges (id) ON DELETE SET NULL,
  content         text NOT NULL,
  title           text,
  is_broadcasted  boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.journal_entries FROM anon, authenticated;
GRANT SELECT ON public.journal_entries TO authenticated;

DROP POLICY IF EXISTS "Users manage own journals" ON public.journal_entries;
CREATE POLICY "Users manage own journals"
  ON public.journal_entries
  FOR ALL
  TO authenticated
  USING (auth.uid() = user_id);

-- ----------------------------------------------------------------------------
-- 5) COMMUNITY_POSTS — publicly viewable; only the author can create their
--    own post. Like/reply/view counts are computed on read (not stored
--    columns), so there is nothing to desync or tamper with here.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.community_posts (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id            uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  journal_entry_id   uuid REFERENCES public.journal_entries (id) ON DELETE SET NULL,
  title              text NOT NULL,
  content            text NOT NULL,
  -- Optional public tag, one of a fixed set enforced below by a CHECK
  -- constraint — a raw API call with an arbitrary tag string is rejected by
  -- Postgres itself, not by client-side validation.
  tag                text,
  view_count         integer NOT NULL DEFAULT 0,
  created_at         timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.community_posts DROP CONSTRAINT IF EXISTS community_posts_tag_check;
ALTER TABLE public.community_posts ADD CONSTRAINT community_posts_tag_check
  CHECK (
    tag IS NULL OR tag IN (
      'Success Stories', 'Struggling', 'Motivation', 'Advice',
      'Question', 'Milestone', 'Accountability', 'Mental Health'
    )
  );

ALTER TABLE public.community_posts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_posts FROM anon, authenticated;
GRANT SELECT, INSERT ON public.community_posts TO authenticated;

DROP POLICY IF EXISTS "View community posts" ON public.community_posts;
CREATE POLICY "View community posts"
  ON public.community_posts
  FOR SELECT
  TO authenticated
  USING (true);

DROP POLICY IF EXISTS "Create own community posts" ON public.community_posts;
CREATE POLICY "Create own community posts"
  ON public.community_posts
  FOR INSERT
  TO authenticated
  WITH CHECK (auth.uid() = user_id);
-- No UPDATE/DELETE -> posts cannot be edited or removed by anyone, including
-- their author, from the client (matches immutable "field report" design).

