ALTER TABLE public.post_likes ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.post_likes TO authenticated;

DROP POLICY IF EXISTS "View post likes" ON public.post_likes;
CREATE POLICY "View post likes" ON public.post_likes FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Manage own post likes" ON public.post_likes;
CREATE POLICY "Manage own post likes"
  ON public.post_likes FOR ALL TO authenticated USING (auth.uid() = user_id);

CREATE TABLE IF NOT EXISTS public.post_replies (
