ALTER TABLE public.post_replies ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.post_replies TO authenticated;

DROP POLICY IF EXISTS "View post replies" ON public.post_replies;
CREATE POLICY "View post replies" ON public.post_replies FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Manage own post replies" ON public.post_replies;
CREATE POLICY "Manage own post replies"
  ON public.post_replies FOR ALL TO authenticated USING (auth.uid() = user_id);

CREATE TABLE IF NOT EXISTS public.post_views (
  post_id     uuid NOT NULL REFERENCES public.community_posts (id) ON DELETE CASCADE,
  viewer_id   uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT timezone('utc', now()),
