);

ALTER TABLE public.post_views ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.post_views TO authenticated;

DROP POLICY IF EXISTS "Users manage own post views" ON public.post_views;
CREATE POLICY "Users manage own post views"
  ON public.post_views FOR ALL TO authenticated USING (auth.uid() = viewer_id) WITH CHECK (auth.uid() = viewer_id);

-- ----------------------------------------------------------------------------
-- 7) BLOCKED_USERS / CONTENT_REPORTS — moderation & safety.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.blocked_users (
